insert into public.page_sections (page, key, data, sort_order)
select x.page, x.key, x.data, x.sort_order
from jsonb_to_recordset($j$[{"page":"home","key":"hero","data":{"title":"CBK INFRA PROJECTS","highlight":"Committed To Superior Quality","subtitle":"Engineering excellence since 2014. Building industrial and commercial spaces across Maharashtra.","cta_primary":"Explore Our Services","cta_secondary":"Contact Us"},"sort_order":0},{"page":"home","key":"stats","data":{"items":["Est. 2014","10+ Years Experience","4 Service Divisions","Chakan, Pune"]},"sort_order":1},{"page":"home","key":"who","data":{"title":"Who We Are","body":"<p>CBK Infra Projects is a Chakan-based engineering firm founded in September 2014. We specialize in civil engineering, fabrication, and interior design — delivering comprehensive design, development, and execution services across various industries with the highest standards of quality, efficiency, and safety.</p>","cards":[{"icon":"Building2","title":"Established Excellence","desc":"Founded in September 2014, grown into a comprehensive civil engineering firm in Chakan, Maharashtra."},{"icon":"Wrench","title":"Comprehensive Services","desc":"Specializing in civil work, PEB structure and shed work, heavy machinery foundations, RCC structural work, trimix flooring and interior design work."},{"icon":"Package","title":"Well-Equipped","desc":"Operating with own machinery and heavy earth-moving equipment, mobilizing resources for projects of any size."}]},"sort_order":2},{"page":"home","key":"services","data":{"title":"Our Core Services","link_text":"Learn More","items":[{"icon":"Building2","title":"Civil Works","desc":"Structural design, RCC, site development, flooring, building construction"},{"icon":"Wrench","title":"Fabrication","desc":"Steel fabrication, PEB sheds, metalwork, precision welding"},{"icon":"Paintbrush","title":"Interior Design","desc":"Turnkey interiors, false ceilings, custom furniture, office spaces"},{"icon":"Mountain","title":"Land Development","desc":"Site leveling, soil embankment, geo textile, contour surveys"}]},"sort_order":3},{"page":"home","key":"mission","data":{"title":"Our Mission & Vision","items":[{"icon":"Star","title":"Industry Leadership","desc":"Becoming a leading provider of innovative engineering solutions"},{"icon":"Lightbulb","title":"Transformative Spaces","desc":"Enhancing functionality, safety, and aesthetics of industrial spaces"},{"icon":"Handshake","title":"Lasting Relationships","desc":"Building long-term partnerships through excellence and trust"}],"quote":"We aim to transform industrial spaces by delivering high-quality, efficient, and customized services through cutting-edge technology, skilled craftsmanship, and a commitment to excellence."},"sort_order":4},{"page":"home","key":"clientele","data":{"title":"Our Clientele","subtitle":"Trusted by leading companies across industries"},"sort_order":5},{"page":"home","key":"industries","data":{"title":"Industries We Serve","items":[{"icon":"Car","label":"Automotive Manufacturing"},{"icon":"Package","label":"Warehousing & Logistics"},{"icon":"UtensilsCrossed","label":"Food & Beverage"},{"icon":"Pill","label":"Pharmaceuticals"},{"icon":"Building","label":"Commercial & Corporate"}]},"sort_order":6},{"page":"home","key":"cta","data":{"title":"Ready to Build Something Exceptional?","text":"Get in touch with our team today for a free project consultation.","button":"Contact Us Today"},"sort_order":7},{"page":"about","key":"hero","data":{"title":"About CBK Infra Projects","subtitle":"A decade of engineering excellence from Chakan, Maharashtra"},"sort_order":8},{"page":"about","key":"story","data":{"title":"Our Story","body":"<p>CBK Infra Projects was founded in September 2014 in Chakan, Maharashtra, with a vision to redefine how industrial and commercial spaces are built. Over the past decade, we have grown from a focused civil engineering firm into a comprehensive multi-disciplinary company offering civil works, fabrication, interior design, land development, electrical, plumbing, and turnkey solutions.</p><p>We operate with our own fleet of heavy equipment and a skilled team of engineers, planners, and technicians — enabling us to take on projects of any scale with confidence and precision.</p>"},"sort_order":9},{"page":"about","key":"values","data":{"title":"Our Core Values","items":[{"icon":"Star","title":"Quality","desc":"We commit to the highest standards in every single project."},{"icon":"Handshake","title":"Integrity","desc":"We build relationships through transparency and reliability."},{"icon":"Lightbulb","title":"Innovation","desc":"We embrace cutting-edge technology and smart engineering."},{"icon":"Leaf","title":"Sustainability","desc":"We incorporate eco-friendly practices and materials."},{"icon":"User","title":"Client-Centricity","desc":"We design solutions around the needs and vision of our clients."}]},"sort_order":10},{"page":"about","key":"objectives","data":{"title":"Our Objectives","items":[{"icon":"Shield","title":"Quality Excellence","desc":"Deliver projects meeting the highest standards of construction quality, safety, and durability."},{"icon":"User","title":"Client Focus","desc":"Understand and fulfill client needs with customized solutions aligned with their vision."},{"icon":"Leaf","title":"Sustainability","desc":"Incorporate environmentally responsible practices to minimize ecological impact."},{"icon":"Lightbulb","title":"Innovation","desc":"Leverage the latest technologies to enhance efficiency, accuracy, and project outcomes."}]},"sort_order":11},{"page":"about","key":"team","data":{"title":"Our Team","items":[{"icon":"HardHat","title":"Civil & Structural Engineers","desc":"Qualified engineers with expertise in designing and executing complex structural projects."},{"icon":"ClipboardList","title":"Project Managers & Supervisors","desc":"Experienced professionals ensuring timely delivery and quality control."},{"icon":"Hammer","title":"Skilled Labor & Technicians","desc":"Well-trained workforce with specialized skills across construction disciplines."},{"icon":"Monitor","title":"CAD Designers & Planners","desc":"Creative professionals translating client visions into detailed technical plans."}]},"sort_order":12},{"page":"about","key":"certs","data":{"title":"Compliance & Certifications","intro":"CBK Infra Projects complies with all statutory regulations and industry standards.","items":[{"title":"ISO 9001:2015","desc":"Quality Management"},{"title":"ISO 45001:2018","desc":"Occupational Health and Safety"},{"title":"GST Registered","desc":"GST: 27BHWPT3693L1Z3"},{"title":"MSME Certified","desc":"Recognized small and medium enterprise"}]},"sort_order":13},{"page":"services","key":"hero","data":{"title":"Our Services","subtitle":"Comprehensive engineering solutions under one roof"},"sort_order":14},{"page":"services","key":"civil","data":{"title":"Civil Works","intro":"From office and industrial building construction to RCC structural works and specialized flooring, our civil division handles every aspect of construction with precision and durability.","points":["Office and industrial building construction","RCC structural works","Retaining and compound walls","STP, ETP, WTP tank construction","Asphalt, bitumen, and trimix flooring","Precast compound walls, curbstones, road dividers"]},"sort_order":15},{"page":"services","key":"foundations","data":{"title":"Structure & Machinery Foundations","intro":"Specialized foundations engineered for heavy industrial machinery, ensuring stability, precision, and long-term performance.","items":[{"title":"Machine Foundation","desc":"Specialized heavy machinery foundations engineered for stability, precision, and long-term performance."},{"title":"Chemical Grouting & Epoxy Flooring","desc":"Chemical grouting and epoxy flooring solutions to ensure durability and protection against environmental factors."},{"title":"Waterproofing & Shuttering","desc":"Waterproofing and shuttering works for industrial applications requiring durability and precision."}]},"sort_order":16},{"page":"services","key":"fabrication","data":{"title":"PEB & Conventional Shed Construction","intro":"Our fabrication division delivers high-quality, customized solutions including shed fabrication, conventional shed work, industrial shed work, railings, platforms, mezzanine floors, and staircases.","steps":[{"step":"01","title":"Design","desc":"Custom steel structure design"},{"step":"02","title":"Fabrication","desc":"Precision metalwork and welding"},{"step":"03","title":"Erection","desc":"Professional installation services"},{"step":"04","title":"Completion","desc":"Quality assurance and handover"}],"extras_title":"Additional Fabrication Services","extras":["PEB shed fabrication and erection","Industrial shed construction","MS/SS railings and staircases","Platforms, mezzanine flooring","Structural welding"]},"sort_order":17},{"page":"services","key":"land","data":{"title":"Land Development Services","intro":"Comprehensive land preparation services that lay the groundwork for successful construction projects.","items":[{"icon":"MapPin","title":"Site Leveling & Grading","desc":"Professional site leveling and grading services to prepare land for construction projects."},{"icon":"Building2","title":"Soil Embankment","desc":"Professional soil management and embankment construction for stable foundations and proper drainage."},{"icon":"Compass","title":"Contour & Geo Textile Survey","desc":"Comprehensive contour surveys and geo textile solutions for soil stabilization and erosion control."}]},"sort_order":18},{"page":"services","key":"interiors","data":{"title":"Interior Design Excellence","intro":"Transforming industrial and commercial spaces with thoughtful, functional, and aesthetic interior solutions.","items":[{"title":"Office Interiors","desc":"Complete office design and execution including workstations, partitions, and storage solutions."},{"title":"Custom Solutions","desc":"Bespoke furniture, cabinetry, and fixtures tailored to specific requirements and aesthetics."},{"title":"Renovation Services","desc":"Reimagining and upgrading existing spaces with modern design elements and functional improvements."}],"tags":["Turnkey office interiors","False ceilings, tiling","Aluminum and glass partitions","Custom furniture and workstations","Renovation and remodeling"]},"sort_order":19},{"page":"services","key":"additional","data":{"title":"Additional Services","items":[{"icon":"Paintbrush","title":"Painting Services","desc":"Structural/industrial painting, decorative and emulsion finishes"},{"icon":"PenTool","title":"Designing & Planning","desc":"2D & 3D architectural planning, RCC and PEB structure planning, interior layout consultancy"},{"icon":"Droplets","title":"Sanitary & Plumbing","desc":"Sewage/stormwater pipeline, complete plumbing systems (UPVC, CPVC, GI, MS, SS), washroom renovation and RCC chambers"},{"icon":"Zap","title":"Electrical Works","desc":"Industrial and commercial electrical installations, lighting, cabling, load management"},{"icon":"Key","title":"Turnkey Solutions","desc":"Lock and key project delivery for civil, fabrication, and interiors; fast-track execution"},{"icon":"Settings","title":"Maintenance Services","desc":"Civil structure repairs, interior and fabrication maintenance, plumbing and electrical support"}]},"sort_order":20},{"page":"approach","key":"hero","data":{"title":"Our Project Management Approach","subtitle":"Structured. Transparent. Delivered on time."},"sort_order":21},{"page":"approach","key":"overview","data":{"text":"<p>CBK Infra Projects adopts a meticulous and structured approach to project management. Each project is managed from inception to completion by a dedicated team of engineers, planners, and site supervisors to ensure timelines, budget control, safety, and quality standards are consistently met.</p>"},"sort_order":22},{"page":"approach","key":"process","data":{"title":"Our Process","step_label":"Step","items":[{"icon":"ClipboardList","step":"01","title":"Planning","desc":"Project scope and requirements analysis"},{"icon":"Play","step":"02","title":"Execution","desc":"Systematic implementation with quality control"},{"icon":"BarChart3","step":"03","title":"Monitoring","desc":"Continuous progress tracking and reporting"},{"icon":"CheckCircle","step":"04","title":"Completion","desc":"Final quality assurance and handover"}]},"sort_order":23},{"page":"approach","key":"equipment","data":{"title":"Equipment & Resources","intro":"We operate a full fleet of in-house heavy equipment, enabling rapid deployment, cost efficiency, and total control over execution timelines.","items":[{"icon":"Truck","title":"Excavators","desc":"High-capacity excavators for efficient earthwork operations"},{"icon":"HardHat","title":"Dozers","desc":"Powerful dozers for site leveling and grading"},{"icon":"Factory","title":"Batching Plants","desc":"Modern batching plants for quality concrete production"},{"icon":"Wrench","title":"Welding & Fabrication Machinery","desc":"Advanced equipment for precision metal fabrication"}]},"sort_order":24},{"page":"work","key":"hero","data":{"title":"Our Work","subtitle":"A selection of civil, fabrication, interior, and land development projects delivered across Maharashtra."},"sort_order":25},{"page":"work","key":"stats","data":{"items":[{"value":"10+","label":"Years Delivering"},{"value":"150+","label":"Projects Executed"},{"value":"50+","label":"Industrial Clients"},{"value":"4","label":"Service Divisions"}]},"sort_order":26},{"page":"work","key":"categories","data":{"title":"Projects Across Every Division","intro":"From RCC structures to turnkey interiors, every project is delivered with the same commitment to quality and timeline.","items":[{"icon":"HardHat","label":"All"},{"icon":"Building2","label":"Civil Works"},{"icon":"Wrench","label":"Fabrication"},{"icon":"Paintbrush","label":"Interiors"},{"icon":"Mountain","label":"Land Development"}]},"sort_order":27},{"page":"work","key":"process","data":{"title":"How We Deliver Every Project","intro":"A consistent process — from first site visit to final handover — keeps quality, safety, and timelines on track.","items":[{"step":"01","title":"Survey & Plan","desc":"Site visit, requirement capture, drawings, and BoQ."},{"step":"02","title":"Design & Approve","desc":"2D/3D plans, structural design, and client sign-off."},{"step":"03","title":"Execute","desc":"Mobilization, fabrication, civil, and interior execution."},{"step":"04","title":"Handover","desc":"Quality checks, snag closure, and on-time handover."}]},"sort_order":28},{"page":"work","key":"cta","data":{"title":"Have a Project in Mind?","text":"Tell us about your site and requirements — we'll put together a plan and a quote.","button":"Start a Project"},"sort_order":29},{"page":"contact","key":"hero","data":{"title":"Contact Us","subtitle":"Let's discuss your next project"},"sort_order":30},{"page":"contact","key":"form","data":{"title":"Send an Enquiry","services":["Civil Works","Fabrication","Interior Design","Land Development","Turnkey Solution","Other"],"success_title":"Thank You!","success_text":"Our team will reach out to you within 24 hours."},"sort_order":31},{"page":"contact","key":"map","data":{"embed_url":"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d30236.69!2d73.86!3d18.76!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3bc2b70c10d3e36f%3A0x506f5b98b0c3e7e4!2sChakan%2C%20Maharashtra!5e0!3m2!1sen!2sin!4v1700000000000"},"sort_order":32}]$j$::jsonb) as x(page text, key text, data jsonb, sort_order int)
