insert into public.projects (title, client, location, category, summary, highlights, cover_url, gallery, sort_order, is_published)
select x.title, x.client, x.location, x.category, x.summary,
       array(select jsonb_array_elements_text(x.highlights)),
       x.cover_url,
       array(select jsonb_array_elements_text(x.gallery)),
       x.sort_order, x.is_published
from jsonb_to_recordset($j$[{"title":"Industrial Shed Fabrication","client":"Leading Automotive OEM","location":"Chakan MIDC, Pune","category":"Fabrication","summary":"<p>Design, fabrication, and erection of a large-span PEB shed engineered for heavy manufacturing operations.</p>","highlights":["PEB shed design and erection","Structural welding and crane support","On-time turnkey delivery"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":0},{"title":"Heavy Machinery Foundation","client":"Precision Equipment Manufacturer","location":"Bhamboli, Pune","category":"Civil Works","summary":"<p>RCC machine foundations engineered for vibration control, load distribution, and long-term operational stability.</p>","highlights":["Reinforced concrete foundation","Chemical grouting and anchoring","Precision alignment and levelling"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":1},{"title":"Turnkey Office Interiors","client":"Corporate HQ Fit-Out","location":"Pune","category":"Interiors","summary":"<p>Complete office interior execution including workstations, partitions, false ceilings, flooring, and lighting.</p>","highlights":["Aluminium and glass partitions","False ceiling and decorative finishes","Custom workstations and cabinetry"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":2},{"title":"RCC Compound Wall & Site Works","client":"Logistics Park","location":"Khed Taluka, Pune","category":"Civil Works","summary":"<p>Precast compound walls, internal roads, and drainage works for a large logistics and warehousing facility.</p>","highlights":["Precast compound wall installation","Asphalt and trimix flooring","Stormwater drainage system"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":3},{"title":"Site Leveling & Land Development","client":"Industrial Plot Owner","location":"Chakan, Maharashtra","category":"Land Development","summary":"<p>End-to-end site preparation including grading, soil embankment, and contour survey for an industrial plot.</p>","highlights":["Site leveling and grading","Soil embankment and compaction","Geo textile and erosion control"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":4},{"title":"Mezzanine Floor & MS Staircases","client":"Warehousing Client","location":"Pune","category":"Fabrication","summary":"<p>Steel mezzanine floors, MS staircases, and safety railings fabricated and erected for storage expansion.</p>","highlights":["Mezzanine floor design and erection","MS/SS railings and staircases","Load-tested handover"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":5},{"title":"Trimix Flooring – Production Bay","client":"F&B Manufacturer","location":"Pune","category":"Civil Works","summary":"<p>High-durability trimix flooring across a production bay engineered for heavy traffic and food-grade conditions.</p>","highlights":["Surface hardener trimix flooring","Joint cutting and sealing","Smooth, dust-free finish"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":6},{"title":"Industrial Painting & Renovation","client":"Existing Facility Upgrade","location":"Chakan MIDC, Pune","category":"Interiors","summary":"<p>Structural and decorative painting across a working facility with minimal disruption to ongoing operations.</p>","highlights":["Structural / industrial painting","Decorative emulsion finishes","Phased execution around production"],"cover_url":null,"gallery":[],"is_published":true,"sort_order":7}]$j$::jsonb) as x(
  title text, client text, location text, category text, summary text,
  highlights jsonb, cover_url text, gallery jsonb, sort_order int, is_published boolean
)
where not exists (select 1 from public.projects);
